import {toLocal,toWorld} from './pose.js';
import {PEOPLE} from './life.js';import {placements,legacyPlacements,insideBody,BY_ID,BODIES,SIZES,METHODS} from './architecture.js';
const slot='tsugime.transport.stage9.v1';
export function snapshot(s){if(s.mode!=='idle'||s.anyLiftActive||s.buildingTransition||((s.atrium?.progress??0)>1e-8&&(s.atrium?.progress??0)<1-1e-8))throw Error('搬送・EVの完了後に保存してください。');return{schema:4,layout:'stage12-atrium',atrium:{progress:(s.atrium?.progress??0)>.5?1:0},loadedInterior:s.loadedInterior,phase:s.phase,experiment:s.experiment,player:s.player,playerAnchor:BY_ID[s.owner]?{body:s.owner,local:toLocal(s.positions[s.owner],s.player)}:null,doors:s.doors,doorTargets:s.experience.doorTargets,doorProgress:s.experience.doorProgress,life:{time:s.life.time,states:s.life.states},items:{counts:s.items.counts,flags:s.items.flags,results:s.items.results,mode:s.items.mode,selected:s.items.selected},trade:s.experience.trade,liftY:s.liftY,localLift:s.localLift,visit:s.experience.visit,dialogue:s.experience.dialogue,clock:s.clock};}
export function restore(s,input){const d=structuredClone(input);if(!d||![0,1,2,3,4].includes(d.schema??0)||!['A','B','C'].includes(d.phase))throw Error('未対応または破損した保存データ');if(d.atrium&&(![0,1].includes(d.atrium.progress)||d.atrium.progress===1&&d.phase!=='B'))throw Error('吹き抜けの保存状態が不正');const e=d.experiment??s.experiment;if(d.loadedInterior&&(d.loadedInterior.body!=='LB1'||d.playerAnchor?.body!=='LB1'||d.playerAnchor.local.x<1.61||d.playerAnchor.local.x>15.6||d.playerAnchor.local.z<.4||d.playerAnchor.local.z>7.6))throw Error('研究所の保存状態が不正');if(d.playerAnchor&&(!BY_ID[d.playerAnchor.body]||!['x','z'].every(k=>Number.isFinite(d.playerAnchor.local?.[k]))))throw Error('保存された建築内座標が不正');if(!SIZES[e.size]||!METHODS[e.method])throw Error('保存された搬送条件が不正');const states=d.life?.states;if(states)for(const n of PEOPLE){const r=states[n.id];if(!r||r.manual!=null&&!['home','work'].includes(r.manual)||!['home','work'].includes(r.location)||!Number.isFinite(r.cover)||r.cover<0||r.cover>1)throw Error('NPC保存状態が不正');}if(d.player&&!['x','y','z','yaw','pitch'].every(k=>Number.isFinite(d.player[k])))throw Error('プレイヤー座標が不正');for(const v of Object.values(d.doorProgress??{}))if(!Number.isFinite(v)||v<0||v>1)throw Error('扉の保存状態が不正');const counts=d.items?.counts??d.inventory??{};for(const v of Object.values(counts))if(!Number.isInteger(v)||v<0)throw Error('所持数が不正');if(!Number.isFinite(d.life?.time??d.clock??0))throw Error('時計が不正');
 s.reset(e);s.phase=d.phase;s.positions=placements(d.phase,e);s.atrium={progress:d.atrium?.progress??0,blocked:false};if(d.player&&['x','y','z','yaw','pitch'].every(k=>Number.isFinite(d.player[k])))s.player=d.player;if(d.player){const old=legacyPlacements(d.phase,e);let anchor=d.playerAnchor;if((d.schema??0)<2){const body=BODIES.find(b=>{const p=old[b.id];if(!p)return false;const q=toLocal(p,d.player);return Math.abs(p.y-d.player.y)<.01&&insideBody(b,q.x,q.z);});if(body)anchor={body:body.id,local:toLocal(old[body.id],d.player)};}if(anchor)s.player={...d.player,...toWorld(s.positions[anchor.body],anchor.local),yaw:d.player.yaw+((old[anchor.body]?.angle??0)-(s.positions[anchor.body].angle??0))*Math.PI/180};}for(const id of Object.keys(s.doors)){s.doors[id]=d.doors?.[id]??false;s.experience.doorTargets[id]=d.doorTargets?.[id]??s.doors[id];s.experience.doorProgress[id]=d.doorProgress?.[id]??(s.doors[id]?1:0);}s.life.time=d.life?.time??d.clock??0;if(states)s.life.states=states;s.items.counts=counts;s.items.flags=d.items?.flags??{};s.items.results=d.items?.results??[];s.items.mode=['browse','use','trade'].includes(d.items?.mode)?d.items.mode:null;s.items.selected=d.items?.selected??null;if(d.trade&&PEOPLE.some(n=>n.id===d.trade)&&s.life.states[d.trade].location==='work'){s.experience.trade=d.trade;s.items.mode='trade';}s.loadedInterior=d.loadedInterior?.body==='LB1'?{body:'LB1'}:null;s.clock=d.clock??0;s.liftY=[-12.8,0,12.8].includes(d.liftY)?d.liftY:12.8;if(d.localLift&&!d.localLift.liftActive)s.localLift=d.localLift;if(d.visit&&PEOPLE.some(n=>n.id===d.visit.npc&&n.home.body===d.visit.body)&&s.life.states[d.visit.npc].location==='home'){s.experience.visit=d.visit;s.experience.lastVisitDoor=PEOPLE.find(n=>n.id===d.visit.npc).home.door;s.experience.focus={...PEOPLE.find(n=>n.id===d.visit.npc),...PEOPLE.find(n=>n.id===d.visit.npc).home};s.experience.blend=1;}if(d.visit?.testModel&&d.visit.body==='CP1'){const door=BY_ID.CP1.doors.find(v=>v.id===d.visit.door);if(door?.capsuleView){s.experience.visit=d.visit;s.experience.visitBody='CP1';s.experience.lastVisitDoor=door.id;s.experience.focus={body:'CP1',camera:door.capsuleView.camera,look:door.capsuleView.look};s.experience.blend=1;}}if(d.dialogue&&PEOPLE.some(n=>n.id===d.dialogue.npc.id))s.experience.dialogue=d.dialogue;s.invalidate();if((d.schema??0)<2&&d.phase==='B'&&s.owner==='W2'){s.player={...s.player,...toWorld(s.positions.P9,{x:15.1,z:12.4})};}if(!s.isFree(s.player.x,s.player.z,s.player.y)&&!s.experience.visit){let safe=null;for(let r=.25;r<=2&&!safe;r+=.25)for(let a=0;a<16;a++){const x=s.player.x+Math.cos(a*Math.PI/8)*r,z=s.player.z+Math.sin(a*Math.PI/8)*r;if(s.isFree(x,z,s.player.y)){safe={x,z};break;}}if(safe)Object.assign(s.player,safe);else Object.assign(s.player,{x:-1.2,z:4,y:[-12.8,0,12.8].includes(s.player.y)?s.player.y:12.8});}s.player.owner=s.owner;s.message='生活時計・所在・所持品・搬送配置を復元しました。';return true;}
export function saveLocal(s,storage=globalThis.localStorage){const data=snapshot(s);storage.setItem(slot,JSON.stringify(data));return data;}
export function loadLocal(s,storage=globalThis.localStorage){const raw=storage.getItem(slot);if(!raw)throw Error('この実験の保存データはありません。');return restore(s,JSON.parse(raw));}
